<?php

namespace App\Http\Controllers;

use App\Http\Requests\ContactRequest;
use Illuminate\Http\RedirectResponse;
use Illuminate\Support\Facades\Http;
use Illuminate\View\View;
use Throwable;

class ContactController extends Controller
{
    public function show(): View
    {
        return view('contact');
    }

    public function send(ContactRequest $request): RedirectResponse
    {
        // SEC-055: honeypot. Same success-looking response, no side effect.
        // (Alternative: Cloudflare Turnstile, field cf-turnstile-response, verified server-side.)
        if ($request->filled('company_url')) {
            return $this->thanks();
        }

        try {
            // >>> the one line the project replaces: the real destination (CRM / webhook / mail) <<<
            Http::timeout(8)->post((string) config('services.contact.webhook_url'), $request->validated())->throw();
        } catch (Throwable $e) { // ConnectionException (timeout) or RequestException (non-2xx)
            report($e);

            abort(502, 'We could not deliver your message. Please try again later.'); // RES-008: never a success page
        }

        return $this->thanks();
    }

    private function thanks(): RedirectResponse
    {
        // POST -> 303 -> GET keeps a refresh from re-posting.
        return redirect()->route('contact', status: 303)->with('status', 'Thank you. Your message was sent.');
    }
}
