Laravel 12 and 13 (PHP 8.2+ / 8.3+; checked on 12.70 and 13.38). Vite::useCspNonce() makes the @vite tag stamp the nonce on its script/style tags; put nonce="{{ Vite::cspNonce() }}" on every other inline <script>/<style>. Laravel/Symfony already sends Cache-Control "no-cache, private" on HTML (meets PRF-008 for HTML), so only the hashed Vite assets need a rule, and that lives in the web server (nginx block below). The bootstrap/app.php blocks of the headers, health-endpoint, robots-sitemap and error-pages recipes are parts of one ->withRouting/->withMiddleware/->withExceptions chain: merge them, each call once. Local `npm run dev` loads from the Vite dev server, which this CSP blocks: test the CSP against `npm run build`.
### file: app/Http/Middleware/SecurityHeaders.php
<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Vite;
use Symfony\Component\HttpFoundation\Response;

class SecurityHeaders
{
    public function handle(Request $request, Closure $next): Response
    {
        Vite::useCspNonce();          // fresh random nonce for this request; @vite stamps it
        $nonce = Vite::cspNonce();

        $response = $next($request);

        // SEC-010 / SEC-075: nonce + 'strict-dynamic' (no unsafe-inline for scripts), object-src, base-uri, frame-ancestors.
        // With the consent loader also add its connect-src / img-src hosts (see that recipe); never add Google hosts to script-src.
        $csp = "default-src 'self'; "
            ."script-src 'self' 'nonce-{$nonce}' 'strict-dynamic'; "
            ."style-src 'self' 'nonce-{$nonce}'; "
            ."img-src 'self' data:; font-src 'self'; connect-src 'self'; "
            ."object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'; "
            .'upgrade-insecure-requests';

        $response->headers->set('Content-Security-Policy', $csp);
        $response->headers->set('X-Content-Type-Options', 'nosniff');
        $response->headers->set('Referrer-Policy', 'strict-origin-when-cross-origin');
        $response->headers->set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');

        // HSTS only on HTTPS. Behind a TLS-terminating proxy, configure trusted proxies so isSecure() is true.
        if ($request->isSecure()) {
            $response->headers->set('Strict-Transport-Security', 'max-age=63072000; includeSubDomains');
        }

        return $response;
    }
}
