use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Route;

// OPS-002: 200 {"status":"ok"} when the app AND the database answer, else 503. Body never carries versions or error text.
Route::get('/healthz', function () {
    try {
        DB::select('select 1'); // replace/extend with the project's other critical dependency
        $ok = true;
    } catch (Throwable $e) {
        report($e);             // the real error goes to the log, never to the response
